#include "eir_c_int.h"

namespace eir {

// Helpers every generated file carries. Division traps on a zero divisor; float to integer
// saturates (NaN is 0). Memory is read and written through casts, so the file is compiled
// with -fno-strict-aliasing.
namespace cemit {

const char* kPrelude = R"C(#include <stdint.h>
#include <stddef.h>
#include <stdarg.h>

#if defined(__GNUC__) || defined(__clang__)
#define __eskc_trap() __builtin_trap()
#else
#define __eskc_trap() (*(volatile int*)0 = 0)
#endif

static void __eskc_copy(void* d, const void* s, size_t n) {
    unsigned char* dp = (unsigned char*)d;
    const unsigned char* sp = (const unsigned char*)s;
    if (dp == sp) return;
    while (n--) *dp++ = *sp++;
}
static int64_t __eskc_sdiv32(int32_t a, int32_t b) { if (!b) __eskc_trap(); return (a == INT32_MIN && b == -1) ? a : a / b; }
static int64_t __eskc_srem32(int32_t a, int32_t b) { if (!b) __eskc_trap(); return (b == -1) ? 0 : a % b; }
static int64_t __eskc_sdiv64(int64_t a, int64_t b) { if (!b) __eskc_trap(); return (a == INT64_MIN && b == -1) ? a : a / b; }
static int64_t __eskc_srem64(int64_t a, int64_t b) { if (!b) __eskc_trap(); return (b == -1) ? 0 : a % b; }
static int64_t __eskc_udiv64(uint64_t a, uint64_t b) { if (!b) __eskc_trap(); return (int64_t)(a / b); }
static int64_t __eskc_urem64(uint64_t a, uint64_t b) { if (!b) __eskc_trap(); return (int64_t)(a % b); }
static int64_t __eskc_f2s(double v, int64_t lo, int64_t hi) {
    if (v != v) return 0;
    if (v <= (double)lo) return lo;
    if (v >= (double)hi) return hi;
    return (int64_t)v;
}
static int64_t __eskc_f2u(double v, uint64_t hi) {
    if (v != v || v <= 0) return 0;
    if (v >= (double)hi) return (int64_t)hi;
    return (int64_t)(uint64_t)v;
}
static int64_t __eskc_iface_data(void* fat) { return fat ? (int64_t)(intptr_t)((void**)fat)[0] : 0; }
)C";

} // namespace cemit

void CEmitterImpl::emitModule(const Module* mod, std::ostream& os) {
    currentMod = mod;
    nameCache.clear();
    throws = moduleThrows(mod);

    os << "/* Generated by the Eskiu EIR C99 backend. Compile with -fno-strict-aliasing. */\n";
    os << kPrelude << "\n";

    recordNames.clear();
    recordDefs.str("");
    findCabiFns(mod);
    std::ostringstream protos;
    std::unordered_set<std::string> seen;
    for (const auto& fn : mod->functions) {
        if (!(fn->isExtern || fn->blocks.empty())) continue;
        AtomicIntrinsic at;
        if (isVaCall(fn->name) || isRuntimeName(fn->name) || parseAtomicIntrinsic(fn->name, at)) continue;
        if (!seen.insert(fn->name).second) continue;
        emitPrototype(fn.get(), protos);
    }
    for (const auto& name : thunkOrder()) {
        const Function* f = mod->getFunction(name);
        if (isCAggregate(f->returnType)) cRecord(f->returnType);
        for (const auto& p : f->params) if (isCAggregate(p.second)) cRecord(p.second);
    }
    os << recordDefs.str() << "\n" << protos.str() << "\n";

    if (moduleNeedsRuntime(mod)) os << runtimeInlineSource(mod) << "\n";
    emitImplicitDecls(mod, os);
    emitGlobalDecls(mod, os);

    seen.clear();
    for (const auto& fn : mod->functions) {
        if (fn->isExtern || fn->blocks.empty() || !seen.insert(fn->name).second) continue;
        emitPrototype(fn.get(), os);
    }
    os << "\n";

    for (const auto& name : thunkOrder()) emitCabiThunk(mod->getFunction(name), os);
    emitGlobalDefs(mod, os);

    seen.clear();
    for (const auto& fn : mod->functions) {
        if (fn->isExtern || fn->blocks.empty() || !seen.insert(fn->name).second) continue;
        emitFunction(fn.get(), os);
    }
}

bool CEmitterImpl::isDefined(const std::string& n) const {
    const Function* f = currentMod->getFunction(n);
    return f && !f->isExtern && !f->blocks.empty();
}

bool CEmitterImpl::isGlobal(const std::string& n) const {
    for (const auto& g : currentMod->globals) if (g.name == n) return true;
    return false;
}

std::string CEmitterImpl::cName(const std::string& n) {
    auto it = nameCache.find(n);
    if (it != nameCache.end()) return it->second;
    const Function* f = currentMod->getFunction(n);
    bool external = (f && (f->isExtern || f->blocks.empty())) || (!f && !isGlobal(n));
    std::string out;
    for (unsigned char c : n) {
        if (isalnum(c) || c == '_') out += static_cast<char>(c);
        else {
            char buf[8];
            snprintf(buf, sizeof buf, "_x%02X", c);
            out += buf;
        }
    }
    if (exportEntry(f)) out = "__eskc_body_" + out;
    else if (!external && n != "main" && cKeywords().count(out)) out = "__eskc_" + out;
    nameCache[n] = out;
    return out;
}

bool CEmitterImpl::cabiSignature(const Function* f) {
    bool rec = isCAggregate(f->returnType);
    for (const auto& p : f->params) rec = rec || isCAggregate(p.second) || isVaListType(p.second);
    return rec;
}

std::string CEmitterImpl::exportName(const std::string& n) {
    std::string body = cName(n);
    return body.substr(std::string("__eskc_body_").size());
}

std::string CEmitterImpl::sanitize(const std::string& prefix, const std::string& v) {
    std::string s = v;
    if (!s.empty() && (s[0] == '%' || s[0] == '@' || s[0] == '$')) s = s.substr(1);
    std::string out = prefix;
    for (unsigned char c : s) {
        if (isalnum(c) || c == '_') out += static_cast<char>(c);
        else {
            char buf[8];
            snprintf(buf, sizeof buf, "_%02X", c);
            out += buf;
        }
    }
    return out;
}

std::string CEmitterImpl::cType(const TypePtr& t) {
    if (!t) return "void*";
    switch (t->kind) {
        case TypeKind::Void: return "void";
        case TypeKind::Int:
            switch (t->bitWidth) {
                case 1: return "uint8_t";
                case 8: return t->isSigned ? "int8_t" : "uint8_t";
                case 16: return t->isSigned ? "int16_t" : "uint16_t";
                case 64: return t->isSigned ? "int64_t" : "uint64_t";
                default: return t->isSigned ? "int32_t" : "uint32_t";
            }
        case TypeKind::Float: return t->bitWidth == 32 ? "float" : "double";
        default: return "void*";
    }
}

char CEmitterImpl::kindOf(const TypePtr& t) {
    if (t && t->isInt()) return 'i';
    if (t && t->isFloat()) return t->bitWidth == 32 ? 'f' : 'd';
    return 'p';
}

int64_t CEmitterImpl::truncConst(int64_t v, const TypePtr& t) {
    if (!t || !t->isInt()) return v;
    switch (t->bitWidth) {
        case 1: return v & 1;
        case 8: return t->isSigned ? static_cast<int64_t>(static_cast<int8_t>(v)) : static_cast<int64_t>(static_cast<uint8_t>(v));
        case 16: return t->isSigned ? static_cast<int64_t>(static_cast<int16_t>(v)) : static_cast<int64_t>(static_cast<uint16_t>(v));
        case 32: return t->isSigned ? static_cast<int64_t>(static_cast<int32_t>(v)) : static_cast<int64_t>(static_cast<uint32_t>(v));
        default: return v;
    }
}

std::string CEmitterImpl::floatConst(double v, bool is32) {
    std::string s;
    if (std::isnan(v)) s = "(0.0/0.0)";
    else if (std::isinf(v)) s = v > 0 ? "(1e308*10.0)" : "(-1e308*10.0)";
    else {
        char buf[64];
        snprintf(buf, sizeof buf, "%a", v);
        s = buf;
    }
    return is32 ? "((float)" + s + ")" : s;
}

std::string CEmitterImpl::escape(const std::string& str) {
    std::ostringstream ss;
    ss << "\"";
    for (unsigned char c : str) {
        if (c == '\n') ss << "\\n";
        else if (c == '\t') ss << "\\t";
        else if (c == '\r') ss << "\\r";
        else if (c == '"') ss << "\\\"";
        else if (c == '\\') ss << "\\\\";
        else if (c == '?') ss << "\\?";
        else if (c < 32 || c >= 127) {
            char buf[8];
            snprintf(buf, sizeof buf, "\\%03o", c);
            ss << buf;
        } else ss << c;
    }
    ss << "\"";
    return ss.str();
}

size_t CEmitterImpl::sizeOf(const TypePtr& t) const {
    if (!t) return 8;
    size_t sz = 0;
    if (t->isStruct() && currentMod) sz = currentMod->getStructSize(t->nominalName());
    if (sz == 0) sz = getTypeSize(t, currentMod);
    if (sz == 0) sz = 8;
    return sz;
}

std::string CEmitterImpl::symAddr(const std::string& n) {
    if (cabiFns.count(n))
        return exportEntry(currentMod->getFunction(n)) ? "((void*)" + exportName(n) + ")"
                                                     : "((void*)__eskc_cabi_" + cName(n) + ")";
    if (currentMod->getFunction(n)) return "((void*)" + cName(n) + ")";
    return "((void*)&" + cName(n) + ")";
}

char CEmitterImpl::opKind(const Operand& op) const {
    if (op.kind == OperandKind::Variable) {
        auto it = varKind.find(op.text);
        if (it != varKind.end()) return it->second;
    }
    if (op.kind == OperandKind::ConstantInt) return 'i';
    if (op.kind == OperandKind::ConstantFloat) return (op.type && op.type->bitWidth == 32) ? 'f' : 'd';
    return 'p';
}

std::string CEmitterImpl::ival(const Operand& op) {
    switch (op.kind) {
        case OperandKind::ConstantInt: return i64Const(truncConst(op.intVal, op.type));
        case OperandKind::ConstantNull: return "INT64_C(0)";
        case OperandKind::ConstantFloat: return "((int64_t)" + floatConst(op.floatVal, false) + ")";
        case OperandKind::ConstantString: return "((int64_t)(intptr_t)" + escape(op.text) + ")";
        case OperandKind::GlobalRef: return "((int64_t)(intptr_t)" + symAddr(op.text) + ")";
        case OperandKind::Variable: {
            if (!varKind.count(op.text)) return "INT64_C(0)";
            char k = opKind(op);
            if (k == 'i') return var(op.text);
            if (k == 'p') return "((int64_t)(intptr_t)" + var(op.text) + ")";
            return "((int64_t)" + var(op.text) + ")";
        }
        default: throw std::runtime_error("EIR C: unsupported operand " + op.str());
    }
}

std::string CEmitterImpl::pval(const Operand& op) {
    switch (op.kind) {
        case OperandKind::ConstantNull: return "((void*)0)";
        case OperandKind::ConstantString: return "((void*)" + escape(op.text) + ")";
        case OperandKind::GlobalRef: return symAddr(op.text);
        case OperandKind::Variable:
            if (!varKind.count(op.text)) return "((void*)0)";
            if (opKind(op) == 'p') return var(op.text);
            return "((void*)(intptr_t)" + ival(op) + ")";
        default: return "((void*)(intptr_t)" + ival(op) + ")";
    }
}

std::string CEmitterImpl::fval(const Operand& op) {
    if (op.kind == OperandKind::ConstantFloat) return floatConst(op.floatVal, false);
    char k = opKind(op);
    if (op.kind == OperandKind::Variable && !varKind.count(op.text)) return "0.0";
    if (k == 'f' || k == 'd') return "((double)" + var(op.text) + ")";
    if (op.type && op.type->isInt() && !op.type->isSigned) return "((double)" + uval(op) + ")";
    return "((double)" + ival(op) + ")";
}

std::string CEmitterImpl::asKind(const Operand& op, char k) {
    if (k == 'i') return ival(op);
    if (k == 'p') return pval(op);
    return "((" + kindType(k) + ")" + fval(op) + ")";
}

std::string CEmitterImpl::asC(const Operand& op, const TypePtr& t) {
    if (t && t->isInt()) return "((" + cType(t) + ")" + ival(op) + ")";
    if (t && t->isFloat()) return "((" + cType(t) + ")" + fval(op) + ")";
    return pval(op);
}

std::unique_ptr<CEmitter> createCEmitter() {
    return std::make_unique<CEmitterImpl>();
}

} // namespace eir
